  "data_catalog": [
    {
      "dataset": "sales_pnl",
      "description": "سود و زیان فروش به تفکیک دستهٔ کالا و ماه",
      "dimensions": [
        "category",
        "month"
      ],
      "measures": [
        "revenue_m",
        "cogs_m",
        "waste_m"
      ]
    }
  ],
  "metric_catalog": [
    {
      "metric": "gross_margin",
      "description": "حاشیهٔ ناخالص",
      "formula": "(فروش منهای بهای تمام‌شده) تقسیم بر فروش",
      "unit": "درصد",
      "dimensions": [
        "category"
      ]
    }
  ],
  "business_context": [
    "برنامهٔ توسعهٔ سالانه شش فروشگاه جدید",
    "زنجیرهٔ ۱۲۰ فروشگاه با مرکز توزیع متمرکز",
    "فروش سازمانی و عمده به بنگاه‌ها بخشی از درآمد است"
  ]
}

TOOL_CALL:
{
  "tool": "compare_periods",
  "arguments": {
    "metrics": [
      "gross_margin"
    ],
    "period_a": "prev_month",
    "period_b": "curr_month"
  }
}

TOOL_OBSERVATION:
{
  "gross_margin_pct": {
    "prev": 26.9,
    "curr": 25.3,
    "change_pp": -1.6
  }
}

